const ozMathematics7Kolay = <(String, String, List<String>, String)>[
  ('Bir okuldaki her öğrenciyi doğum gününün ayına eşleyen kural için hangisi doğrudur?', 'Fonksiyondur; her öğrencinin tek bir doğum ayı vardır', ['Fonksiyon değildir; aynı ayda doğan öğrenciler vardır', 'Fonksiyon değildir; bazı aylarda doğan öğrenci olmayabilir', 'Yalnızca öğrenci sayısı 12 ise fonksiyondur'], 'Fonksiyon olmak için her girdinin tam bir çıktısı olması yeter. Farklı öğrencilerin aynı aya gitmesi ya da bazı ayların boş kalması fonksiyon olmayı engellemez.'),
  ('Bir sınıfta her öğrenciyi kendi okul numarasına eşleyen kural ile her okul numarasını o numaralı öğrenciye eşleyen kural için hangisi doğrudur?', 'İkisi de fonksiyondur ve birbirinin tersidir', ['Yalnız birincisi fonksiyondur', 'Yalnız ikincisi fonksiyondur', 'İkisi de fonksiyondur ama birbirinin tersi olamaz'], 'Okul numaraları tektir; öğrenci ile numara arasında bire bir eşleme vardır. Bu yüzden her iki yön de fonksiyondur ve biri diğerinin tersidir.'),
  ('Düzlemde y² = x bağıntısı, x ≥ 0 için y\'yi x\'in fonksiyonu olarak tanımlar mı?', 'Hayır; x = 4 için y = 2 ve y = −2 elde edilir', ['Evet; her x ≥ 0 için en az bir y değeri bulunabilir', 'Evet; çünkü x her y için tektir', 'Hayır; çünkü x negatif olamaz'], 'Pozitif bir x için iki farklı y değeri vardır. Bir girdiye iki çıktı karşılık geldiğinden bağıntı y\'yi x\'in fonksiyonu yapmaz.'),
  ('Fonksiyon tanımında \'tanım kümesinin her elemanı\' ifadesinin karşılanmaması hangi durumda olur?', 'Tanım kümesinde görüntüsü olmayan bir eleman kalırsa', ['Değer kümesinde hiçbir elemanla eşlenmeyen bir eleman olursa', 'İki eleman aynı görüntüye giderse', 'Görüntü kümesi değer kümesine eşit olursa'], 'Fonksiyonda tanım kümesindeki hiçbir eleman açıkta kalamaz. Değer kümesinde boşta eleman kalması ya da iki elemanın aynı yere gitmesi ise serbesttir.'),
  ('Bir kitapçının günlük kârı, satılan kitap sayısı n için K(n) = 12n − 150 TL ile veriliyor. Kitapçının zarar etmemesi için günde en az kaç kitap satması gerekir?', '13', ['12,5', '15', '10'], 'K(n) ≥ 0 için 12n ≥ 150, n ≥ 12,5 olmalıdır. Kitap sayısı tam sayı olduğundan en az 13 kitap gerekir.'),
  ('Bir cismin yere düşüş süresi saniye cinsinden t olmak üzere düştüğü yol d(t) = 5t² metre ile veriliyor. Cisim ilk 3 saniyede kaç metre düşer?', '45', ['22,5', '30', '90'], 'd(3) = 5·3² = 5·9 = 45 metredir.'),
  ('f(x) = (x − 1)/(x² − 1) ve g(x) = 1/(x + 1) fonksiyonları için hangisi doğrudur?', 'f\'nin tanım kümesinde 1 yoktur, g\'ninkinde vardır', ['İki fonksiyon tamamen eşittir', 'g\'nin tanım kümesi f\'ninkinden daha küçük bir kümedir', 'İkisinin de tanım kümesi ℝ − {−1}\'dir'], 'f, x = 1 ve x = −1\'de tanımsızdır; g yalnız x = −1\'de tanımsızdır. Sadeleşmiş kurallar aynı olsa da tanım kümeleri farklı olduğundan fonksiyonlar eşit değildir.'),
  ('√(x² − 9) ifadesinin gerçek sayı olabilmesi için x hangi kümede bulunmalıdır?', '(−∞, −3] ∪ [3, ∞)', ['[−3, 3]', '[3, ∞) ∪ {−3}', '(−3, 3)'], 'x² − 9 ≥ 0 için x² ≥ 9, yani |x| ≥ 3 olmalıdır. Bu da x ≤ −3 ya da x ≥ 3 demektir.'),
  ('Bir fonksiyonun kuralı verilip tanım kümesi belirtilmediğinde genellikle hangi küme tanım kümesi kabul edilir?', 'Kuralın gerçek sayılarda anlamlı olduğu en geniş küme', ['Yalnız pozitif gerçek sayılar', 'Yalnız tam sayılardan oluşan küme, çünkü kural tam sayılarda tanımlıdır', 'Görüntü kümesiyle tam olarak aynı olan küme'], 'Aksi söylenmedikçe tanım kümesi, kuralın gerçek sayı sonucu verdiği bütün x değerlerinden oluşan en geniş kümedir.'),
  ('f(x) = 1/(|x| − 2) fonksiyonu kaç gerçek sayı için tanımsızdır?', '2', ['1', '0', 'Sonsuz çoklukta'], '|x| − 2 = 0 eşitliği x = 2 ve x = −2 için sağlanır. Fonksiyon yalnız bu iki noktada tanımsızdır.'),
  ('f(x) = √(16 − x²) fonksiyonunun görüntü kümesi hangisidir?', '[0, 4]', ['[−4, 4]', '[0, 16]', '(0, 4)'], 'Tanım kümesi [−4, 4]\'tür. Kök içi 0 ile 16 arasında değiştiğinden fonksiyon 0 ile 4 arasındaki her değeri alır.'),
  ('Bir su faturasında 40 TL sabit bedele her metreküp için 15 TL eklenmektedir. 12 m³ su kullanan bir ailenin faturası kaç TL olur?', '220', ['180', '192,5', '260'], 'F(m) = 40 + 15m kuralıyla F(12) = 40 + 180 = 220 TL bulunur.'),
  ('Bir aracın kalan yakıtı L(k) = 48 − 0,06k litre (k: gidilen km) ile modelleniyor. −0,06 sayısı neyi ifade eder?', 'Kilometre başına harcanan yakıt miktarını', ['Depodaki başlangıç yakıtını', 'Deponun tamamen boşalacağı kilometre değerini', 'Saatte harcanan yakıt miktarını'], 'Doğrusal modelde x\'in katsayısı birim değişimdir. Her kilometrede yakıt 0,06 litre azalır; 48 ise başlangıçtaki yakıttır.'),
  ('İki doğrusal maliyet modelinin grafikleri bir noktada kesişiyorsa bu nokta günlük dilde neyi ifade eder?', 'İki seçeneğin aynı maliyeti verdiği kullanım miktarını', ['İki seçeneğin de tamamen ücretsiz olduğu durumu', 'Maliyetlerin en düşük olduğu anı', 'Birim ücretlerin eşit olduğu durumu'], 'Kesişim noktasında aynı girdi için iki fonksiyonun çıktısı eşittir. Bu, iki seçeneğin o kullanım miktarında aynı tutarı tuttuğunu gösterir.'),
  ('Gerçek sayılarda tanımlı bir sabit fonksiyonun grafiği nasıl bir çizgidir?', 'x eksenine paralel bir doğru', ['y eksenine paralel bir doğru', 'Orijinden geçen eğik bir doğru', 'y = x doğrusuna dik bir doğru'], 'Sabit fonksiyon f(x) = c biçimindedir; her noktanın ordinatı c olduğundan grafik yatay bir doğrudur.'),
  ('Birim fonksiyonun grafiği koordinat düzleminde hangi açıyı oluşturur?', 'Birinci ve üçüncü bölgeyi ikiye bölen 45°\'lik doğru', ['x eksenine dik bir doğru', 'İkinci ve dördüncü bölgeleri ikiye bölen 135°\'lik doğru', 'Orijinden geçmeyen yatay bir doğru'], 'Birim fonksiyon y = x\'tir; x ekseniyle pozitif yönde 45° açı yapar ve birinci ile üçüncü bölgelerin açıortayıdır.'),
  ('Sabit bir f fonksiyonu için f(2) + f(5) = 14 veriliyor. f(100) − f(−7) farkı kaçtır?', '0', ['7', '14', '−7'], 'Sabit fonksiyonda her girdinin görüntüsü aynıdır: 2f = 14, f(x) = 7. Fark 7 − 7 = 0 olur.'),
  ('Hangi durum doğrusal bir fonksiyonla modellenmeye en uygundur?', 'Saatlik sabit ücretle çalışan birinin kazancı', ['Her yıl değeri ikiye katlanan bir yatırımın değeri', 'Yere bırakılan topun düşüş yolu', 'Yarı ömrüyle azalan radyoaktif madde'], 'Sabit saat ücretinde kazanç her saat aynı miktar artar; bu doğrusal büyümedir. Diğerleri üstel ya da ikinci dereceden değişir.'),
  ('Bir f fonksiyonu x ≤ 2 için x² − 1, x > 2 için 7 − x kuralıyla tanımlanmıştır. f(2) + f(3) toplamı kaçtır?', '7', ['9', '8', '5'], 'x = 2 birinci parçaya girer: f(2) = 3. x = 3 ikinci parçaya girer: f(3) = 4. Toplam 7\'dir.'),
  ('Dilimli bir ücret tarifesi grafiğe dökülürse hangi görünüm beklenir?', 'Eğimi dilim sınırlarında değişen birleşik doğru parçaları', ['Tek bir doğru', 'Tepesi aşağıda bir parabol', 'Yatay asimptota yaklaşan kesintisiz bir eğri'], 'Her dilimde birim fiyat sabit olduğundan grafik doğru parçasıdır; dilim değişince birim fiyat, yani eğim değişir. Parçalar sınırda birleşir.'),
  ('⌊x⌋, x\'ten büyük olmayan en büyük tam sayıyı göstermek üzere ⌊3,9⌋ + ⌊−0,5⌋ toplamı kaçtır?', '2', ['3', '4', '1'], '⌊3,9⌋ = 3 ve ⌊−0,5⌋ = −1\'dir. Toplam 2 olur.'),
  ('⌊2x − 1⌋ = 4 eşitliğini sağlayan x\'lerin kümesi hangisidir?', '[2,5; 3)', ['(2,5; 3]', '[2,5; 3,5)', '[2,5; 3]'], '4 ≤ 2x − 1 < 5 olmalıdır. Buradan 5 ≤ 2x < 6, yani 2,5 ≤ x < 3 bulunur.'),
  ('⌈x⌉, x\'ten küçük olmayan en küçük tam sayı olmak üzere ⌈−2,4⌉ − ⌈1,2⌉ farkı kaçtır?', '−4', ['−5', '−3', '−1'], '⌈−2,4⌉ = −2 ve ⌈1,2⌉ = 2\'dir. Fark −2 − 2 = −4 olur.'),
  ('⌊x⌋ + ⌊−x⌋ ifadesi x tam sayı değilken hangi değeri alır?', '−1', ['0', '1', '−2x'], 'x = n + k (0 < k < 1) ise ⌊x⌋ = n ve ⌊−x⌋ = −n − 1\'dir. Toplam −1\'dir; x tam sayıysa sonuç 0 olur.'),
  ('{x} = x − ⌊x⌋ ondalık kısım fonksiyonu olmak üzere {−3,25} değeri kaçtır?', '0,75', ['0,25', '−0,25', '−0,75'], '⌊−3,25⌋ = −4 olduğundan {−3,25} = −3,25 − (−4) = 0,75\'tir. Ondalık kısım her zaman [0, 1) aralığındadır.'),
  ('x − ⌊x⌋ ondalık kısım fonksiyonunun görüntü kümesi hangisidir?', '[0, 1)', ['(0, 1)', '[0, 1]', '(−1, 1)'], 'x tam sayıyken değer 0\'dır; diğer durumlarda 0 ile 1 arasında bir değer alır ama 1\'e hiç ulaşmaz.'),
  ('x − ⌊x⌋ fonksiyonu periyodiktir. Esas periyodu kaçtır?', '1', ['2', '1/2', 'π'], '⌊x + 1⌋ = ⌊x⌋ + 1 olduğundan (x + 1) − ⌊x + 1⌋ = x − ⌊x⌋ olur. 1\'den küçük pozitif bir periyot yoktur.'),
  ('f(x) = |x − 1| + |x + 1| fonksiyonunun −1 ≤ x ≤ 1 aralığındaki kuralı hangisidir?', '2', ['2x', '−2x', 'x + 2'], 'Bu aralıkta |x − 1| = 1 − x ve |x + 1| = x + 1\'dir. Toplam (1 − x) + (x + 1) = 2 sabitidir.'),
  ('⌊x/3⌋ = 2 eşitliğini sağlayan tam sayıların toplamı kaçtır?', '21', ['18', '24', '15'], '2 ≤ x/3 < 3 için 6 ≤ x < 9; tam sayılar 6, 7, 8\'dir. Toplam 21 olur.'),
  ('Pozitif bir sayının ondalık kısmı ile o sayının tam kısmının toplamı neye eşittir?', 'Sayının kendisine', ['Sayının iki katına', 'Sıfıra', 'Sayının tam kısmına'], 'x = ⌊x⌋ + {x} tanımından tam kısım ile ondalık kısmın toplamı sayının kendisidir.'),
  ('y = |x| grafiğinin biçimi en iyi hangi ifadeyle betimlenir?', 'Tepesi orijinde olan, yukarı açılan V harfi', ['Tepesi orijinde olan, aşağı açılan ters V harfi', 'Orijinden geçen ve eğimi 1 olan tek doğru', 'Orijin etrafında simetrik duran S biçimli eğri'], 'x ≥ 0 için y = x, x < 0 için y = −x olduğundan grafik orijinde birleşen iki yarım doğrudur ve yukarı açılan V görünümündedir.'),
  ('y = −|x + 2| + 5 grafiğinin tepe noktası ve açılış yönü hangisidir?', '(−2, 5) ve aşağı doğru', ['(2, 5) ve aşağı doğru', '(−2, 5) ve yukarı doğru', '(−2, −5) ve aşağı doğru'], '|x + 2| ifadesi x = −2\'de sıfırdır; burada y = 5 olur. Önündeki eksi işareti V\'yi ters çevirir, bu yüzden grafik aşağı açılır.'),
  ('y = 3|x − 1| grafiğinin sağ kolunun eğimi kaçtır?', '3', ['1', '−3', '1/3'], 'x ≥ 1 için y = 3(x − 1) = 3x − 3\'tür; sağ kolun eğimi 3\'tür. Sol kolun eğimi ise −3\'tür.'),
  ('y = |x| − 3 grafiğinin x ekseniyle sınırladığı bölgenin alanı kaç birimkaredir?', '9', ['6', '18', '4,5'], 'Grafik x eksenini x = ±3\'te keser, tepe noktası (0, −3)\'tür. Tabanı 6, yüksekliği 3 olan üçgenin alanı 9\'dur.'),
  ('y = |2x + 6| grafiğinin simetri ekseni hangi doğrudur?', 'x = −3', ['x = 3', 'x = −6', 'y = −3 doğrusu'], 'İfade 2|x + 3| biçiminde yazılır ve x = −3\'te sıfırlanır. V grafiği bu düşey doğruya göre simetriktir.'),
  ('|x − 2| = k denkleminin yalnız bir çözümü olması için k kaç olmalıdır?', '0', ['2', '−2', 'Herhangi bir pozitif sayı'], 'y = k doğrusu V\'nin tepesinden (y = 0) geçerse tek ortak nokta olur. k > 0 için iki, k < 0 için hiç çözüm yoktur.'),
  ('|x| = x/2 + 3 denkleminin kaç gerçek çözümü vardır?', '2', ['1', '0', 'Sonsuz sayıda'], 'x ≥ 0\'da x = x/2 + 3 ise x = 6. x < 0\'da −x = x/2 + 3 ise x = −2. İkisi de koşulu sağladığından iki çözüm vardır.'),
  ('y = |x| grafiği ile y = x + 1 doğrusu kaç noktada kesişir?', '1', ['2', '0', 'Sonsuz sayıda'], 'x ≥ 0\'da x = x + 1 çelişkidir. x < 0\'da −x = x + 1 ise x = −1/2 bulunur. Tek kesişim noktası (−1/2, 1/2)\'dir.'),
  ('y = |x| grafiği ile y = x doğrusunun ortak noktalarının kümesi nedir?', 'x ≥ 0 olan bütün noktalar', ['Yalnız orijin', 'Hiçbir ortak nokta yoktur; doğru V\'nin altındadır', 'x ≤ 0 olan bütün noktalar'], 'x ≥ 0 için |x| = x olduğundan sağ kol doğruyla çakışır; sonsuz sayıda ortak nokta vardır. x < 0\'da ise |x| > x\'tir.'),
  ('||x| − 3| = 1 denkleminin kaç gerçek kökü vardır?', '4', ['2', '3', '8'], '|x| − 3 = ±1 ise |x| = 4 ya da |x| = 2. Bunlar x = ±4 ve x = ±2 olmak üzere dört kök verir.'),
  ('y = f(x − 5) grafiği y = f(x) grafiğinden nasıl elde edilir?', '5 birim sağa kaydırılarak', ['5 birim sola kaydırılarak', '5 birim yukarı kaydırılarak', '5 birim aşağı kaydırılarak'], 'x yerine x − 5 yazmak, eski grafikteki her noktanın 5 birim sağda tekrar görünmesini sağlar.'),
  ('Görüntü kümesi [−1, 5] olan f için y = f(x) − 3 fonksiyonunun görüntü kümesi nedir?', '[−4, 2]', ['[2, 8]', '[−1, 5]', '[−4, 5]'], 'Düşey öteleme her çıktıdan 3 çıkarır: alt sınır −4, üst sınır 2 olur. Tanım kümesi değişmez.'),
  ('y = −f(−x) dönüşümü y = f(x) grafiğine geometrik olarak ne yapar?', 'Orijine göre yansıtır', ['Yalnız x eksenine göre yansıtır', 'Yalnız y eksenine göre yansıtır', 'y = x doğrusuna göre yansıtır'], 'Hem apsisin hem ordinatın işaretinin değişmesi, iki eksene göre art arda yansımaya, yani orijine göre yansımaya eşittir.'),
  ('Hangi fonksiyonun grafiği y eksenine göre yansıtıldığında kendisiyle çakışmaz?', 'y = x³ + 1', ['y = x² + 1', 'y = |x| − 2', 'y = 4 − x⁴'], 'y eksenine göre yansımada çakışmak için f(−x) = f(x) gerekir. (−x)³ + 1 = −x³ + 1 olduğundan x³ + 1\'e eşit değildir; diğerleri çift fonksiyondur.'),
  ('Bir fonksiyonun kuralında x yerine 2x yazılması, yani y = f(2x) eğrisine geçilmesi grafiğin biçimini nasıl değiştirir?', 'Yatay doğrultuda yarıya daraltılarak', ['Yatay doğrultuda 2 kat genişletilerek', 'Düşey doğrultuda 2 kat uzatılarak', '2 birim sola kaydırılarak'], 'f(2x)\'te eski grafikteki (a, b) noktası (a/2, b) noktasına gider; bu y eksenine doğru yarıya sıkışmadır.'),
  ('Bir eğrinin denklemi y = f(x) iken y = |f(x)| eğrisini çizmek için hangi işlem yapılır?', 'x ekseninin altındaki parçalar eksene göre yukarı katlanır', ['y ekseninin solundaki parçalar silinir', 'Grafiğin tamamı x eksenine göre yansıtılır, hiçbir parça korunmaz', 'Sağdaki parça y eksenine göre sola kopyalanır'], '|f(x)| negatif çıktıların işaretini değiştirir. Bu, x ekseni altında kalan bölümlerin eksene göre simetriğinin alınması demektir.'),
  ('Mutlak değerli |x² − 4| ifadesi kaç farklı x gerçek sayısı için 3 değerini alır?', '4', ['2', '3', '6'], 'x² − 4 = 3 ise x = ±√7; x² − 4 = −3 ise x = ±1. Toplam dört kesişim vardır.'),
  ('f(x) = x − 3 olmak üzere y = f(|x|) grafiğinin en alt noktası hangisidir?', '(0, −3)', ['(3, 0)', '(−3, 0)', '(0, 3)'], 'f(|x|) = |x| − 3\'tür; bu V grafiğinin tepesi x = 0\'da olup y = −3\'tür.'),
  ('Gerçek sayılarda tanımlı tek bir fonksiyonun grafiği için hangisi her zaman doğrudur?', 'Orijinden geçer', ['y eksenine göre simetriktir', 'Görüntü kümesi pozitif sayılardır', 'Hiç artan aralığı yoktur'], 'Tek fonksiyonda f(0) = −f(0) olduğundan f(0) = 0\'dır. Tanım kümesi 0\'ı içerince grafik orijinden geçmek zorundadır.'),
  ('f(x) = x + 1 fonksiyonu tek ve çift olma bakımından nasıldır?', 'Ne tek ne de çifttir', ['Tek fonksiyondur', 'Çift fonksiyondur', 'Hem tek hem çift fonksiyondur'], 'f(−x) = −x + 1\'dir. Bu ne f(x) = x + 1\'e ne de −f(x) = −x − 1\'e eşittir.'),
  ('f ve g tek fonksiyonlar olmak üzere f∘g bileşkesi hangi türdendir?', 'Tek', ['Çift', 'Ne tek ne çift', 'Sabit'], 'f(g(−x)) = f(−g(x)) = −f(g(x)) olduğundan bileşke tektir.'),
  ('Hangi fonksiyonun grafiği orijine göre simetriktir?', 'y = 1/x', ['y = 1/x²', 'y = |x| + 1', 'y = x² − x'], '1/(−x) = −1/x olduğundan y = 1/x tek fonksiyondur ve grafiği orijine göre simetriktir.'),
  ('Bir fonksiyonun bir aralıkta azalan olduğu, çizimi incelenerek nasıl anlaşılır?', 'Soldan sağa ilerledikçe eğri aşağı iner', ['Eğri baştan sona x ekseninin altında kalır', 'Eğri y eksenine yaklaşır', 'Eğrinin ordinatları negatiftir'], 'Azalanlık, x büyüdükçe f(x)\'in küçülmesidir; grafik soldan sağa doğru alçalır. Değerlerin negatif olması azalanlık anlamına gelmez.'),
  ('Bir f fonksiyonu için f(x) = 0 denkleminin çözümleri, fonksiyonun çiziminde neye karşılık gelir?', 'Grafiğin x eksenini kestiği ya da değdiği noktaların apsislerine', ['Grafiğin y eksenini kestiği tek noktanın ordinat değerine karşılık gelir', 'Grafiğin en yüksek noktasının apsisine', 'Grafiğin y = x doğrusunu kestiği noktalara'], 'f(x) = 0 demek ordinatın sıfır olmasıdır. Bu noktalar x ekseni üzerindedir ve apsisleri denklemin çözümleridir.'),
  ('Bir hisse senedinin fiyat grafiği bir hafta boyunca soldan sağa sürekli aşağı iniyor. Bu, fiyat fonksiyonu için ne anlama gelir?', 'Hafta boyunca azalandır', ['Hafta boyunca negatiftir', 'Hafta boyunca sabittir', 'Haftanın ortasında en küçüktür'], 'Grafiğin soldan sağa inmesi, zaman ilerledikçe değerin düştüğünü, yani fonksiyonun azalan olduğunu gösterir.'),
  ('f(x) = x² fonksiyonunun x = 1\'den x = 4\'e kadar ortalama değişim hızı kaçtır?', '5', ['3', '15', '7,5'], '[f(4) − f(1)]/(4 − 1) = (16 − 1)/3 = 5\'tir.'),
  ('Bir fonksiyonun [a, b] aralığındaki ortalama değişim hızı, eğrisi üzerinde geometrik olarak neye karşılık gelir?', '(a, f(a)) ve (b, f(b)) noktalarını birleştiren kesenin eğimine', ['Grafiğin a noktasındaki yüksekliğine', 'Grafik ile x ekseni ve x = a, x = b doğruları arasında kalan alana', 'Aralığın uzunluğuna'], 'Ortalama değişim hızı [f(b) − f(a)]/(b − a) olup iki uç noktadan geçen doğrunun (kesenin) eğimidir.'),
  ('Bir fonksiyonun periyodik olması ne demektir?', 'Grafiği eşit aralıklarla aynen tekrar eder', ['Grafiği her yerde artandır', 'Grafiği orijine göre simetriktir', 'Grafiği x büyüdükçe sabit bir değere giderek daha çok yaklaşır'], 'Her x için f(x + T) = f(x) olacak biçimde pozitif bir T sayısı varsa fonksiyon periyodiktir; grafik her T birimde kendini tekrar eder.'),
  ('Bir sıcaklık önce Celsius\'tan Kelvin\'e, sonra Kelvin\'den başka bir ölçeğe çevriliyor. Matematiksel olarak bu işlem hangi kavrama örnektir?', 'Fonksiyonların bileşkesine', ['İki ayrı fonksiyonun toplamının alınmasına', 'Bir fonksiyonun tersine', 'İki fonksiyonun çarpımına'], 'Bir dönüşümün çıktısı ikinci dönüşümün girdisi olarak kullanıldığından bu işlem bileşkedir.'),
  ('Artan bir fonksiyonun tersi için hangisi doğrudur?', 'Tersi de artandır', ['Tersi her zaman azalandır', 'Tersi sabit fonksiyondur', 'Tersi artan da azalan da olabilir'], 'y = x\'e göre yansımada yükselen eğri yine yükselen eğri olur. a < b ise f⁻¹(a) < f⁻¹(b) olmak zorundadır.'),
  ('Grafiği y = x doğrusuna göre kendisine simetrik olan bir fonksiyon hakkında ne söylenebilir?', 'Kendi tersine eşittir', ['Çift fonksiyondur', 'Sabit fonksiyondur', 'Periyodik fonksiyondur'], 'Ters fonksiyonun grafiği y = x\'e göre yansımadır. Yansıma grafiği değiştirmiyorsa fonksiyon kendi tersidir; örneğin f(x) = 1/x.'),
  ('f(x) = 6 − x fonksiyonunun tersi aşağıdakilerden hangisidir?', 'Kendisi, yani 6 − x', ['x − 6', 'x + 6', '1/(6 − x)'], 'y = 6 − x ise x = 6 − y olur; ters kural yine 6 − x\'tir. Grafik y = x\'e dik olduğundan bu doğruya göre simetriktir.'),
  ('ℝ\'den ℝ\'ye tanımlı f(x) = |x| fonksiyonu için hangisi doğrudur?', 'Ne birebir ne de örtendir', ['Hem birebir hem örtendir', 'Birebirdir ama örten değildir', 'Örtendir ama birebir değildir'], 'f(−1) = f(1) olduğundan birebir değildir. Negatif sayılar hiç görüntü olmadığından ℝ\'ye örten de değildir.'),
  ('Doğal sayılardan doğal sayılara tanımlı f(n) = 2n fonksiyonu için hangisi doğrudur?', 'Birebirdir ama örten değildir', ['Örtendir ama birebir değildir', 'Hem birebir hem de örten olan bir fonksiyondur', 'Ne birebir ne örtendir'], 'Farklı sayıların iki katları farklıdır; birebirdir. Tek sayılar hiçbir doğal sayının iki katı olmadığından örten değildir.'),
  ('Hangi fonksiyon gerçek sayılardan gerçek sayılara birebir değildir?', 'f(x) = x² − 4x', ['f(x) = 5 − 2x', 'f(x) = x³ + 2', 'f(x) = 2x + 7'], 'x² − 4x için f(0) = f(4) = 0\'dır; iki farklı girdi aynı çıktıya gider. Diğerleri kesin artan ya da kesin azalandır.'),
  ('Bir fonksiyonun tersinin de bir fonksiyon olabilmesi için asıl fonksiyon hangi özelliği taşımalıdır?', 'Birebir ve örten olmalıdır', ['Çift olmalıdır', 'Sürekli ve sınırlı olmalıdır', 'Doğrusal olmalıdır'], 'Tersin her girdinin tek görüntüsü olması birebirlik, tanım kümesinin tamamında tanımlı olması örtenlik gerektirir.'),
  ('f(x) = 3x − 2 için 2f(x) − f(2x) ifadesinin sadeleşmiş hali nedir?', '−2', ['0', '6x − 2', '2 − 12x'], '2f(x) = 6x − 4 ve f(2x) = 6x − 2\'dir. Fark −2 olur.'),
  ('f ve g artan fonksiyonlar ise aşağıdakilerden hangisi kesinlikle artandır?', 'f + g', ['f − g', 'f · g', 'f / g'], 'İki artan fonksiyonun toplamı artandır. Fark artan olmayabilir; çarpım ve bölüm ise negatif değerler yüzünden artan olmayabilir.'),
  ('Her x ≠ 0 için f(x) + 2f(1/x) = 3x eşitliği sağlanıyor. f(2) kaçtır?', '−1', ['2', '1', '−0,5'], 'x = 2: f(2) + 2f(1/2) = 6. x = 1/2: f(1/2) + 2f(2) = 3/2. İkinciden f(1/2) = 3/2 − 2f(2); yerine yazınca f(2) + 3 − 4f(2) = 6, f(2) = −1.'),
  ('Her x için f(x + 1) = 2f(x) ve f(0) = 3 ise f(4) kaçtır?', '48', ['24', '11', '96'], 'Her adımda değer ikiye katlanır: f(1) = 6, f(2) = 12, f(3) = 24, f(4) = 48.'),
  ('y = √x grafiğinin başlangıç noktası ve genel görünümü hangisidir?', 'Orijinden başlayıp sağa doğru giderek yataylaşan yükselen eğri', ['Orijinden başlayıp sola doğru uzanan yükselen eğri', 'Orijinden geçen ve iki yöne sonsuza uzanan doğru', 'Orijinden başlayıp sağa doğru giderek daha da dikleşen yükselen eğri'], 'Tanım kümesi [0, ∞)\'dur ve fonksiyon artandır; ancak artış hızı x büyüdükçe azalır, bu yüzden eğri gittikçe yataylaşır.'),
  ('y = √(x − 3) + 2 grafiğinin başladığı uç nokta hangisidir?', '(3, 2)', ['(−3, 2)', '(2, 3)', '(3, −2)'], 'Kök içi x = 3\'te sıfırdır ve y = 2 olur. Eğri bu noktadan başlayıp sağa doğru uzanır.'),
  ('y = −√x grafiği hangi bölgede yer alır?', 'Dördüncü bölgede', ['Birinci bölgede', 'İkinci bölgede', 'Üçüncü bölgede ve x ekseninin altında'], 'x ≥ 0 ve y ≤ 0 olduğundan eğri orijinden başlayıp dördüncü bölgeye doğru uzanır.'),
  ('y = √(4 − x) grafiği koordinat eksenlerini hangi noktalarda keser?', '(4, 0) ve (0, 2)', ['(−4, 0) ve (0, 2)', '(4, 0) ve (0, 4)', '(2, 0) ve (0, 4)'], 'y = 0 için 4 − x = 0, x = 4. x = 0 için y = √4 = 2\'dir.'),
  ('Küp alma kuralı y = x³ ile ilgili doğru bilgi hangisidir?', 'Her yerde artandır ve orijine göre simetriktir', ['Yalnız x > 0 için tanımlıdır', 'y eksenine göre simetriktir ve en küçük değeri 0\'dır', 'En küçük değeri 0\'dır'], 'x³ tek fonksiyondur ve kesin artandır; görüntü kümesi bütün gerçek sayılardır.'),
  ('y = x³ ile y = x grafikleri kaç noktada kesişir?', '3', ['1', '2', 'Sonsuz sayıda'], 'x³ = x ise x(x² − 1) = 0; x = −1, 0, 1 olmak üzere üç kesişim vardır.'),
  ('y = k/x (k > 0) fonksiyonunun grafiği hangi bölgelerde yer alır?', 'Birinci ve üçüncü bölgede', ['Birinci ve ikinci bölgede', 'İkinci ve dördüncü bölgede', 'Yalnız birinci bölgede'], 'x > 0 için y > 0, x < 0 için y < 0 olur. Grafik birinci ve üçüncü bölgede iki koldan oluşan bir hiperboldür.'),
  ('y = 1/x grafiği x → ∞ ve x → 0⁺ iken nasıl davranır?', 'Sırasıyla 0\'a yaklaşır ve sınırsız büyür', ['Sırasıyla sınırsız büyür ve sıfır değerine yaklaşır', 'İki durumda da 0\'a yaklaşır', 'İki durumda da 1\'e yaklaşır'], 'Büyük x için 1/x küçülür ve sıfıra yaklaşır. Pozitif tarafta sıfıra yaklaşan x için 1/x sınırsız büyür.'),
  ('y = 2/(x − 3) + 1 grafiğinin yatay ve düşey asimptotları hangi doğrulardır?', 'y = 1 ve x = 3', ['y = 3 ve x = 1', 'y = 2 ve x = 3', 'y = 1 ve x = −3'], 'y = 2/x grafiği 3 birim sağa ve 1 birim yukarı ötelenmiştir; asimptotlar da aynı ölçüde kayar.'),
  ('Üstel terimin önünde eksi işareti bulunan −2ˣ + 4 kuralı hangi değerleri alabilir?', '(−∞, 4)', ['(4, ∞)', '(−∞, 4]', '(0, 4)'], '2ˣ > 0 olduğundan −2ˣ < 0, yani −2ˣ + 4 < 4\'tür. Alt sınır olmadığından görüntü kümesi (−∞, 4)\'tür.'),
  ('y = log₂x grafiğinin y = 2ˣ grafiğiyle ilişkisi nedir?', 'y = x doğrusuna göre birbirinin simetriğidir', ['x eksenine göre birbirinin simetriği olan iki eğridir', 'y eksenine göre birbirinin simetriğidir', 'Orijine göre birbirinin simetriğidir'], 'log₂x ile 2ˣ birbirinin ters fonksiyonudur; ters fonksiyonların grafikleri y = x doğrusuna göre simetriktir.'),
  ('Üç tabanlı logaritma eğrisi y = log₃x yatay ekseni nerede keser?', '(1, 0)', ['(0, 1)', '(3, 0)', '(0, 3)'], 'log₃x = 0 ise x = 3⁰ = 1\'dir. Tüm logaritma fonksiyonları (1, 0) noktasından geçer.'),
  ('Tabanı 1/2 olan logaritma fonksiyonunun eğrisi için doğru betimleme hangisidir?', 'Azalandır ve (1, 0) noktasından geçer', ['Artandır ve (0, 1) noktasından geçer', 'Azalandır ve dikey ekseni (0, 1) noktasında keser', 'Artandır ve (1, 0) noktasından geçer'], 'Taban 1\'den küçükken x büyüdükçe logaritma küçülür. log_a 1 = 0 olduğundan grafik her zaman (1, 0)\'dan geçer.'),
  ('y = log₂(x + 4) grafiğinin düşey asimptotu hangi doğrudur?', 'x = −4', ['x = 4', 'x = 0', 'y = −4'], 'Logaritmanın içi sıfıra yaklaşırken değer −∞\'a gider. x + 4 = 0 ise x = −4 düşey asimptottur.'),
  ('y = log x (on tabanlı) fonksiyonu x 10\'dan 1 000\'e çıkarken değeri ne kadar artar?', '2', ['990', '100', '3'], 'log 10 = 1 ve log 1 000 = 3\'tür. Artış 2\'dir; logaritma büyük çarpımsal değişimleri küçük toplamsal değişimlere çevirir.'),
  ('V(t) = 1 200·(0,9)ᵗ modelinde 0,9 çarpanı neyi gösterir?', 'Her dönemde değerin %10 azaldığını', ['Her dönemde değerin %90 azaldığını', 'Her dönemde değerin 0,9 birim azaldığını', 'Başlangıç değerinin 0,9 olduğunu'], 'Çarpan 1\'den küçükse azalma vardır; 1 − 0,9 = 0,1 olduğundan her dönemde değer %10 azalır.'),
  ('Bir miktar eşit zaman aralıklarında hep aynı oranda çoğalıyorsa bu durum hangi fonksiyon türüyle modellenir?', 'Üstel fonksiyon', ['Doğrusal fonksiyon', 'Sabit fonksiyon', 'Mutlak değer fonksiyonu'], 'Eşit aralıklarda sabit miktar artış doğrusal, sabit oranda (çarpanla) artış ise üstel büyümedir.'),
  ('y = x² ile y = 2x − 1 grafikleri kaç ortak noktaya sahiptir?', '1', ['2', '0', '3'], 'x² = 2x − 1 ise (x − 1)² = 0 olur; tek ortak nokta (1, 1)\'dir ve doğru parabole bu noktada teğettir.'),
  ('Artan 2ˣ eğrisi ile azalan −x + 1 doğrusu düzlemde kaç kez buluşur?', '1', ['0', '2', 'Sonsuz sayıda'], '2ˣ artan, −x + 1 azalandır; bu yüzden en çok bir kez kesişirler. x = 0\'da ikisi de 1 olduğundan tam bir kesişim vardır.'),
  ('y = |x − 1| ile y = 2 doğrusunun kesişim noktaları arasındaki uzaklık kaç birimdir?', '4', ['2', '3', '1'], '|x − 1| = 2 ise x = 3 ya da x = −1\'dir. Noktalar arası uzaklık 3 − (−1) = 4\'tür.'),
  ('Ters orantı hiperbolü y = 1/x ile birim fonksiyonun doğrusu kaç ortak nokta paylaşır?', '2', ['1', '0', '4'], '1/x = x ise x² = 1, x = ±1. Kesişim noktaları (1, 1) ve (−1, −1)\'dir.'),
  ('Bir denklem f(x) = g(x) biçimine getirildiğinde kök sayısı grafik yardımıyla nasıl bulunur?', 'y = f(x) ve y = g(x) eğrilerinin kesişim noktaları sayılarak', ['Yalnız y = f(x) eğrisinin x eksenini kestiği yerler sayılarak', 'Eğrilerin y eksenini kestiği noktalar karşılaştırılarak', 'İki eğrinin en yüksek noktaları karşılaştırılarak'], 'f(x) = g(x) eşitliğini sağlayan her x, iki eğrinin aynı yükseklikte olduğu, yani kesiştiği bir noktaya karşılık gelir.'),
  ('√x > x eşitsizliği hangi aralıkta sağlanır?', '(0, 1)', ['(1, ∞)', '[0, 1]', '(0, ∞)'], 'Eğriler x = 0 ve x = 1\'de kesişir. 0 < x < 1 için √x > x, örneğin √0,25 = 0,5 > 0,25\'tir.'),
  ('f(x) = max{x, 3 − x} fonksiyonunun alabileceği en küçük değer kaçtır?', '1,5', ['0', '3', '1'], 'İki doğru x = 1,5\'te kesişir ve burada ikisi de 1,5\'tir. Bu noktanın iki yanında büyük olan değer artar; en küçük değer 1,5\'tir.'),
  ('g(x) = min{x², 4} fonksiyonunun grafiği nasıl tarif edilir?', '|x| ≤ 2\'de parabol, dışında y = 4 yatay doğrusu', ['|x| ≤ 2\'de y = 4 doğrusu, |x| > 2 olduğunda ise y = x² parabolü', 'Her yerde y = x² parabolü', 'Her yerde y = 4 doğrusu'], 'x² ≤ 4 iken küçük olan x²\'dir; |x| > 2 için x² > 4 olduğundan değer 4\'te sabitlenir.'),
  ('f(x) = max{g(x), h(x)} fonksiyonunun grafiği g ve h grafiklerinden nasıl elde edilir?', 'Her x için iki grafikten üstte olan parça alınır', ['Her x için iki grafikten altta olan parça alınır', 'Her x için iki grafiğin ordinatları toplanarak yeni nokta bulunur', 'İki grafiğin ortalaması alınır'], 'Büyük değer, düzlemde yukarıda olan noktadır. Bu yüzden max fonksiyonu her x\'te üstteki eğriyi izler.'),
  ('x² − 9 ifadesinin işaretini veren sgn(x² − 9) kuralı hangi değerleri üretebilir?', '{−1, 0, 1}', ['{−1, 1}', '{0, 1}', '[−1, 1] aralığı'], 'x² − 9 ifadesi |x| < 3\'te negatif, |x| = 3\'te sıfır, |x| > 3\'te pozitiftir. Üç değerin hepsi alınır.'),
  ('Yarıçapı r olan bir dairenin alanını çevresi C cinsinden veren fonksiyon hangisidir?', 'A(C) = C²/(4π)', ['A(C) = C²/(2π)', 'A(C) = πC²', 'A(C) = C²/π'], 'C = 2πr ise r = C/(2π)\'dir. A = πr² = π·C²/(4π²) = C²/(4π) bulunur.'),
  ('f(x) = |x + 5| + |x − 1| fonksiyonunun grafiği hangi düşey doğruya göre simetriktir?', 'x = −2', ['x = 2', 'x = −5', 'x = 3'], 'Grafik, kırılma noktaları −5 ile 1\'in tam ortasına göre simetriktir: (−5 + 1)/2 = −2.'),
  ('f(x) = (x − 2)³ + 1 fonksiyonunun grafiği hangi noktaya göre simetriktir?', '(2, 1)', ['(−2, 1)', '(2, −1)', '(0, 0)'], 'y = x³ orijine göre simetriktir. 2 sağa, 1 yukarı öteleme simetri merkezini (2, 1)\'e taşır.'),
  ('f(x) = 1/(x − 3) + 2 grafiğinin simetri merkezi hangi noktadır?', '(3, 2)', ['(−3, 2)', '(2, 3)', '(3, −2)'], 'y = 1/x orijine göre simetriktir; 3 sağa ve 2 yukarı ötelemeyle simetri merkezi asimptotların kesiştiği (3, 2) noktası olur.'),
  ('Bir karenin köşegen uzunluğu d iken alanını veren fonksiyon hangisidir?', 'A(d) = d²/2', ['A(d) = d²', 'A(d) = d²/4', 'A(d) = 2d²'], 'Kenar a ise d = a√2\'dir. Alan a² = d²/2 bulunur.'),
  ('Uzaklık-zaman eğrisinin eğiminin negatif olması hareket hakkında ne söyler?', 'Hareketli başlangıç noktasına yaklaşmaktadır', ['Hareketli durmaktadır', 'Hareketli hızlanmaktadır', 'Hareketli giderek artan hızla başlangıçtan uzaklaşmaktadır'], 'Negatif eğim, zaman ilerledikçe uzaklığın azaldığı anlamına gelir; yani hareketli başlangıca doğru gelmektedir.'),
  ('\'Toprağa dikilen bir fidan, dikildiği günden bu yana geçen süreye bağlı olarak uzar.\' cümlesinde bağımlı değişken olan büyüklük hangisidir?', 'Fidanın boyu', ['Geçen süre', 'Toprağın türü', 'Dikim tarihi'], 'Boy, süreye göre değişen büyüklüktür; süre bağımsız, boy bağımlı değişkendir.'),
  ('f(x) = x² + 3x için f(x + 1) ifadesinin açılmış hali hangisidir?', 'x² + 5x + 4', ['x² + 3x + 1', 'x² + 5x + 1', 'x² + 4x + 4'], '(x + 1)² + 3(x + 1) = x² + 2x + 1 + 3x + 3 = x² + 5x + 4\'tür.'),
  ('f(x) = 2x² ise f(a + h) − f(a) farkının sadeleşmiş hali hangisidir?', '4ah + 2h²', ['2h²', '4ah', '2a² + 2h²'], '2(a + h)² − 2a² = 2a² + 4ah + 2h² − 2a² = 4ah + 2h²\'dir.'),
  ('f(3) = 10 yazımında 3 ve 10 sayıları sırasıyla neyi gösterir?', '3 girdi, 10 ise ona karşılık gelen çıktıdır', ['3 çıktı, 10 girdidir', '3 fonksiyonun eğimini, 10 ise y eksenini kestiği noktayı gösterir', 'İkisi de fonksiyonun katsayılarıdır'], 'f(a) = b yazımı, a girdisinin f altında b\'ye gittiğini anlatır; grafikte (3, 10) noktasıdır.'),
  ('f(x) = 1/x için [f(x + 1) − f(x)] ifadesinin sadeleşmiş hali hangisidir?', '−1/(x(x + 1))', ['1/(x(x + 1))', '1', '−1/x²'], '1/(x + 1) − 1/x = (x − (x + 1))/(x(x + 1)) = −1/(x(x + 1)) olur.'),
  ('f(x) = 3x − 1 ise f(f(x)) − 3f(x) ifadesi neye eşittir?', '−1', ['0', '9x − 4', '−3'], 'f(f(x)) = 3f(x) − 1 olduğundan fark −1 olur; f(x) ne olursa olsun sonuç aynıdır.'),
  ('Aşağıdaki noktalardan hangisi y = 2x² − 3 fonksiyonunun grafiği üzerindedir?', '(−2, 5)', ['(2, 1)', '(−1, 1)', '(0, 3)'], 'x = −2 için y = 2·4 − 3 = 5 olur. Diğer noktalar kurala uymaz.'),
  ('y = f(x) grafiği (5, −1) noktasından geçiyorsa hangi bilgi kesindir?', 'f(5) = −1', ['f(−1) = 5', 'f(5) = 1', 'f(0) = 5'], 'Grafik üzerindeki (a, b) noktası f(a) = b anlamına gelir.'),
  ('y = −3x + 5 doğrusu koordinat düzleminin hangi bölgesinden geçmez?', 'Üçüncü bölgeden', ['Birinci bölgeden', 'İkinci bölgeden', 'Dördüncü bölgeden'], 'Doğru y eksenini (0, 5)\'te, x eksenini (5/3, 0)\'da keser; azalandır. Birinci, ikinci ve dördüncü bölgelerden geçer, üçüncüye uğramaz.'),
  ('y = x² + 1 grafiği koordinat düzleminin hangi bölgelerinde bulunur?', 'Yalnız birinci ve ikinci bölgede', ['Dört bölgenin tamamında', 'Yalnız birinci bölgede', 'Birinci ve dördüncü bölgede'], 'x² + 1 ≥ 1 > 0 olduğundan grafik her zaman x ekseninin üstündedir; x pozitifken birinci, negatifken ikinci bölgededir.'),
  ('Bir fonksiyonun üstten sınırlı olması ne demektir?', 'Hiçbir değerinin aşamadığı bir üst sınır vardır', ['Değerleri sonsuza kadar artar', 'En büyük değerini tanım kümesinde mutlaka bir noktada alır', 'Değerleri yalnız pozitiftir'], 'f(x) ≤ M olacak biçimde bir M sayısı varsa f üstten sınırlıdır. Bu sınıra ulaşılması gerekmez.'),
  ('Aşağıdaki fonksiyonlardan hangisi gerçek sayılarda hem alttan hem üstten sınırlıdır?', 'f(x) = 4/(x² + 1)', ['f(x) = x²', 'f(x) = 2ˣ', 'f(x) = x³'], 'x² + 1 ≥ 1 olduğundan 0 < 4/(x² + 1) ≤ 4\'tür. x² ve 2ˣ üstten, x³ hiçbir yönden sınırlı değildir.'),
  ('f(x) = (4x + 1)/(2x − 6) fonksiyonunun yatay asimptotu hangi doğrudur?', 'y = 2', ['y = 4', 'x = 3', 'y = −1/6'], 'Pay ve paydanın dereceleri eşittir; yatay asimptot baş katsayıların oranıdır: 4/2 = 2.'),
  ('f(x) = (x + 3)/(x² − 9) fonksiyonunun grafiğinde x = −3 noktasında ne vardır?', 'Bir boşluk (delik); düşey asimptot değil', ['Düşey asimptot', 'Grafiğin x eksenini kestiği ve işaret değiştirdiği nokta', 'Grafiğin en yüksek noktası'], 'Sadeleşme sonrası 1/(x − 3) elde edilir; x = −3\'te fonksiyon tanımsızdır ama değerler sonlu bir sayıya yaklaşır. Bu, grafikte bir deliktir; düşey asimptot x = 3\'tür.'),
  ('f(x) = (2x − 4)/(x + 1) grafiği x eksenini ve y eksenini hangi noktalarda keser?', '(2, 0) ve (0, −4)', ['(−1, 0) ve (0, 2)', '(2, 0) ve (0, 4)', '(−2, 0) ve (0, −4)'], 'Pay sıfır olunca 2x − 4 = 0, x = 2. x = 0 için f(0) = −4/1 = −4\'tür.'),
  ('Bir rasyonel fonksiyonun grafiğinin düşey asimptotları genellikle nerede bulunur?', 'Paydayı sıfır yapan ama payı sıfır yapmayan x değerlerinde', ['x = 0 doğrusunda, her rasyonel fonksiyonda aynı yerde', 'Payı sıfır yapan x değerlerinde, yani fonksiyonun sıfırlarında', 'Fonksiyonun en büyük değerini aldığı yerde'], 'Payda sıfıra yaklaşırken pay sıfırdan farklı kalırsa değerler sınırsız büyür; bu noktada düşey asimptot oluşur.'),
  ('Bir fonksiyon hangi biçimlerde gösterilebilir?', 'Sözel, tablo, cebirsel kural ya da grafikle', ['Yalnız cebirsel bir formülle', 'Yalnız koordinat düzleminde grafikle', 'Yalnız sıralı ikililerden oluşan sonsuz listeyle'], 'Fonksiyon bir eşlemedir; bu eşleme sözle anlatılabilir, tabloyla, formülle ya da grafikle gösterilebilir.'),
  ('|x − 5| < 2 eşitsizliği sayı doğrusunda hangi anlama gelir?', '5\'e uzaklığı 2\'den az olan sayılar', ['2\'ye uzaklığı 5\'ten az olan sayılar', '5\'ten 2 fazla olan sayılar', 'Orijine uzaklığı 7\'den az olan bütün sayılar'], '|x − a| ifadesi x ile a arasındaki uzaklıktır. Bu yüzden çözüm (3, 7) aralığıdır.'),
  ('y = |x + 1| eğrisinin y = 3 doğrusunun altında kaldığı x değerleri hangi aralıktadır?', '(−4, 2)', ['(−2, 4)', '(−3, 3)', '(−∞, −4) ∪'], '|x + 1| < 3 ise −3 < x + 1 < 3, yani −4 < x < 2\'dir.'),
  ('y = 1/x grafiği hangi dönüşümlerle y = (x + 1)/x grafiğine dönüşür?', '1 birim yukarı öteleme', ['1 birim sola öteleme', '1 birim sağa öteleme', 'x eksenine göre yansıma'], '(x + 1)/x = 1 + 1/x\'tir. Bu, 1/x\'e 1 eklemek, yani grafiği 1 birim yukarı kaydırmaktır.'),
  ('y = x² grafiği y eksenine göre yansıtılırsa hangi grafik elde edilir?', 'Kendisi; grafik değişmez', ['y = −x², yani aşağı açılan parabol', 'y = x² + 1', 'y = (x − 1)²'], '(−x)² = x² olduğundan grafik çift fonksiyondur ve y eksenine göre yansıma onu değiştirmez.'),
  ('y = f(x) ile y = f(x) + c grafikleri arasındaki düşey uzaklık her x için kaçtır?', '|c|', ['c²', '2c', 'x + c'], 'Aynı x değerinde iki ordinat arasındaki fark c\'dir; uzaklık |c| olur ve x\'e bağlı değildir.'),
  ('Bir f fonksiyonu x ≤ 0 için −x, x > 0 için x² kuralına uyuyor. f(f(−2)) kaçtır?', '4', ['−4', '2', '16'], 'f(−2) = −(−2) = 2\'dir. 2 > 0 olduğundan f(2) = 4 olur.'),
  ('Mutlak değer eğrisi y = |x| ile üstel eğri y = 2ˣ düzlemde kaç kez kesişir?', '1', ['0', '2', '3'], 'x ≥ 0\'da 2ˣ her zaman x\'ten büyüktür, kesişim yoktur. x < 0\'da |x| azalan, 2ˣ artandır; x = −1\'de 1 > 1/2, x = 0\'da 0 < 1 olduğundan bu bölgede tam bir kesişim vardır.'),
  ('Küp eğrisi y = x³ ile azalan y = 2 − x doğrusunun ortak noktası kaç tanedir?', '1', ['3', '2', '0'], 'x³ artan, 2 − x azalan olduğundan grafikleri en çok bir kez kesişir; x = 1 bu kesişimdir.'),
  ('Bir hız-zaman eğrisinin yatay olduğu bölümde hareket nasıldır?', 'Sabit hızlıdır', ['Hareketli durmaktadır', 'Düzgün hızlanmaktadır', 'Geri dönmektedir'], 'Hız-zaman eğrisinde yataylık hızın değişmediğini gösterir; bu, hareketin durduğu anlamına gelmez, hız sıfırdan farklı olabilir.'),
  ('Bir f fonksiyonunun en büyük değeri 5\'tir. f(x) = 6 denkleminin kaç çözümü vardır?', 'Hiç çözümü yoktur', ['En az bir çözümü vardır', 'Tam bir çözümü vardır', 'Sonsuz sayıda çözümü vardır'], 'En büyük değer 5 ise fonksiyon hiçbir yerde 6\'ya ulaşamaz; y = 6 doğrusu grafiği kesmez.'),
  ('x² − 4|x| ifadesinin −3 değerini aldığı gerçek sayılar kaç tanedir?', '4', ['2', '3', '0'], 'x ≥ 0 için x² − 4x + 3 = 0, x = 1 ya da 3. Fonksiyon çift olduğundan x = −1 ve −3 de çözümdür.'),
  ('0 < x < 1 aralığında x, x² ve x³ değerleri için hangi sıralama her zaman doğrudur?', 'x³ < x² < x', ['x < x² < x³', 'x² < x < x³', 'x³ < x < x²'], '1\'den küçük pozitif bir sayıyı kendisiyle çarpmak onu küçültür. Örneğin 0,5; 0,25; 0,125 sıralaması x³ < x² < x\'i gösterir.'),
  ('y = x⁴ ile y = x⁵ grafiklerinin genel biçimleri arasındaki temel fark hangisidir?', 'x⁴ y eksenine göre, x⁵ orijine göre simetriktir', ['İkisi de y eksenine göre simetriktir', 'x⁴ orijine göre, x⁵ y eksenine göre simetriktir', 'İkisi de orijine göre simetriktir'], 'Çift kuvvetler çift fonksiyon, tek kuvvetler tek fonksiyondur. Bu yüzden x⁴ U benzeri, x⁵ ise S benzeri bir biçime sahiptir.'),
  ('y = x² ve y = x⁴ grafikleri hangi noktalarda kesişir?', '(−1, 1), (0, 0) ve (1, 1)', ['Yalnız (0, 0) ve (1, 1)', 'Yalnız (1, 1)', '(−1, −1), (0, 0) ve (1, 1)'], 'x² = x⁴ ise x²(x² − 1) = 0; x = 0, 1, −1 olur ve bu noktalarda y değerleri 0, 1, 1\'dir.'),
  ('Doğru orantı fonksiyonu y = kx\'in grafiği için hangisi her zaman doğrudur?', 'Orijinden geçen bir doğrudur', ['y eksenini k noktasında keser', 'x eksenine paraleldir', 'Orijinden geçmeyen bir doğrudur'], 'x = 0 için y = 0 olduğundan grafik orijinden geçer; eğimi k olan bir doğrudur.'),
  ('Hangi durumda bir miktarın büyümesi zamanla \'yavaşlayarak\' sürer?', 'Logaritmik büyümede', ['Üstel büyümede', 'Doğrusal büyümede', 'İkinci dereceden büyümede'], 'Logaritmik fonksiyon artmaya devam eder ama artış hızı giderek azalır; eşit süre artışlarında daha küçük değer artışları olur.'),
  ('y = log₂x fonksiyonunda girdi iki katına çıkarıldığında çıktı nasıl değişir?', '1 artar', ['2 katına çıkar', '2 artar', 'Karesine eşit olacak biçimde büyür'], 'log₂(2x) = log₂2 + log₂x = 1 + log₂x olur. Girdideki her ikiye katlama çıktıya yalnız 1 ekler.'),
  ('y = x^(1/3) ile y = x³ fonksiyonları arasındaki ilişki nedir?', 'Birbirinin tersidir', ['Birbirinin aynısıdır', 'Biri diğerinin y eksenine göre yansımasıdır', 'Biri diğerinin çarpmaya göre tersidir'], '∛(x³) = x ve (∛x)³ = x olduğundan bu iki fonksiyon birbirinin ters fonksiyonudur; grafikleri y = x\'e göre simetriktir.'),
  ('Aşağıdaki fonksiyonlardan hangisi kendi tersine eşittir?', 'f(x) = −x', ['f(x) = x + 1', 'f(x) = 2x', 'f(x) = x³'], 'f(f(x)) = −(−x) = x olduğundan −x kendi tersidir. Diğerlerinde f(f(x)) ≠ x\'tir.'),
  ('Örten fonksiyon kavramını en doğru açıklayan ifade hangisidir?', 'Değer kümesindeki her eleman en az bir elemanın görüntüsüdür', ['Tanım kümesindeki her elemanın farklı görüntüsü vardır', 'Tanım kümesi ile değer kümesi aynıdır', 'Fonksiyon her yerde artandır'], 'Örtenlikte görüntü kümesi değer kümesine eşittir; değer kümesinde boşta eleman kalmaz.'),
  ('f: [0, 3] → B, f(x) = x² + 1 fonksiyonu örten olduğuna göre B kümesi hangisidir?', '[1, 10]', ['[0, 9]', '[1, 4]', '[0, 10]'], '[0, 3]\'te x² + 1 artandır; f(0) = 1, f(3) = 10\'dur. Örtenlik için B görüntü kümesine eşit olmalıdır.'),
  ('f(x) = 4x/(x + 2) fonksiyonu hangi değeri hiçbir x için almaz?', '4', ['−2', '0', '2'], 'y(x + 2) = 4x ise x(y − 4) = −2y, x = −2y/(y − 4) olur. y = 4 için x bulunamaz.'),
  ('f(x) = 5x − 2 için (f∘f⁻¹)(13) kaçtır?', '13', ['3', '63', '1'], 'Bir fonksiyon ile tersinin bileşkesi birim fonksiyondur; girdi değişmeden çıkar.'),
  ('f ve g birebir ve örten fonksiyonlar ise (f∘g)⁻¹ hangisine eşittir?', 'g⁻¹∘f⁻¹', ['f⁻¹∘g⁻¹', 'f∘g', 'g∘f'], 'Önce g, sonra f uygulanır; geri alırken önce f\'yi, sonra g\'yi geri almak gerekir. Bu yüzden sıra ters döner.'),
  ('f(x) = x + 4 ve g(x) = 2x olduğuna göre (f∘g)⁻¹(10) kaçtır?', '3', ['7', '24', '8'], '(f∘g)(x) = 2x + 4\'tür. 2x + 4 = 10 ise x = 3 bulunur.'),
  ('Bir A kümesinden B kümesine tanımlı her fonksiyon için hangisi doğrudur?', 'A × B kartezyen çarpımının bir alt kümesidir', ['A × B kartezyen çarpımına eşittir', 'B × A kartezyen çarpımının alt kümesidir', 'A ile B\'nin birleşimidir'], 'Fonksiyon, (girdi, çıktı) sıralı ikililerinden oluşan özel bir bağıntıdır; bu ikililer A × B\'nin elemanlarıdır.'),
  ('Tanım kümesi {2, 3, 4} olan bir bağıntının sıralı ikilileri (2, 5), (3, 5), (4, 6) ve (2, 7)\'dir. Bu bağıntı neden fonksiyon değildir?', '2\'nin iki farklı görüntüsü vardır', ['5 iki farklı elemanın görüntüsü olmuştur', '4 elemanının görüntüsü yalnızca bir tanedir', 'Görüntülerin tamamı tanım kümesinin dışındadır'], 'Fonksiyonda her girdinin tek görüntüsü olmalıdır; 2 hem 5\'e hem 7\'ye eşlenmiştir. İki girdinin aynı görüntüye gitmesi ise serbesttir.'),
  ('f(x) = 3x − 8 fonksiyonu ile tersinin grafikleri hangi noktada kesişir?', '(4, 4)', ['(−4, −4)', '(8, 8)', '(0, −8)'], 'Artan bir fonksiyon ile tersinin kesişimi y = x üzerindedir. 3x − 8 = x ise x = 4 bulunur.'),
  ('f: A → B gösteriminde A ve B kümeleri sırasıyla neyi ifade eder?', 'A tanım kümesi, B değer kümesidir', ['A görüntü kümesi, B tanım kümesidir', 'A değer kümesi, B ise görüntü kümesi olan kümedir', 'A ile B\'nin kesişimi fonksiyonun kendisidir'], 'Ok işaretinin solundaki küme girdilerin alındığı tanım kümesi, sağındaki küme çıktıların bulunduğu değer kümesidir.'),
  ('Birebir ve örten bir fonksiyonun tersinin görüntü kümesi hangisidir?', 'Asıl fonksiyonun tanım kümesi', ['Asıl fonksiyonun görüntü kümesi', 'Gerçek sayılar kümesi', 'Asıl fonksiyonun değer kümesinin tümleyeni'], 'Ters fonksiyon çıktıları yeniden girdilere götürür; bu yüzden tersinin çıktıları asıl fonksiyonun girdileridir.'),
  ('Bir modelin tanım kümesinin, kuralın matematiksel olarak tanımlı olduğu en geniş kümeden daha dar seçilmesinin nedeni nedir?', 'Bağlamın getirdiği fiziksel ya da mantıksal kısıtlar', ['Kuralın grafiğinin koordinat düzleminde hiçbir biçimde çizilememesi', 'Değer kümesinin gerçek sayılar olmaması', 'Fonksiyonun birebir olmaması'], 'Örneğin uzunluk ya da adet negatif olamaz; bu tür kısıtlar tanım kümesini daraltır.'),
  ('f(x) = |x − 1| + |x − 4| + |x − 6| fonksiyonunun en küçük değeri kaçtır?', '5', ['3', '11', '6'], 'Mutlak değerler toplamı, noktaların ortancasında, yani x = 4\'te en küçük olur: 3 + 0 + 2 = 5.'),
  ('f(x) = |x − 3| − |x + 1| fonksiyonunun alabileceği en büyük değer kaçtır?', '4', ['2', '3', '6'], 'Uzaklık farkı, iki nokta arasındaki uzaklığı (4) aşamaz. x ≤ −1 için f(x) = (3 − x) − (−x − 1) = 4 olur.'),
  ('f(x) = |2x − 8| fonksiyonu [0, 6] aralığında hangi en büyük değeri alır?', '8', ['4', '0', '12'], 'x = 0\'da |−8| = 8, x = 6\'da |4| = 4, x = 4\'te 0\'dır. En büyük değer 8\'dir.'),
  ('f(x) = |x − a| fonksiyonu için hangi ifade her a için doğrudur?', 'En küçük değeri 0\'dır ve x = a\'da alınır', ['En küçük değeri a\'dır', 'En büyük değeri a\'dır', 'x = 0 noktasında en küçük değerini alır ve bu değer a\'ya eşittir'], 'Mutlak değer negatif olamaz; |x − a| = 0 yalnız x = a için sağlanır.'),
  ('Bir grafiğin yatay ekseninde zaman, dikey ekseninde hız varsa grafiğin eğimi hangi büyüklüğü verir?', 'İvmeyi', ['Yolu', 'Konumu', 'Kütleyi'], 'Hızın zamana göre değişim oranı ivmedir; hız-zaman grafiğinde eğim ivmeyi gösterir.'),
  ('f\'nin en küçük değeri −2\'dir. g(x) = −3f(x) fonksiyonu için hangisi kesindir?', 'En büyük değeri 6\'dır', ['En küçük değeri 6\'dır', 'En küçük değeri −6\'dır', 'En büyük değeri −6\'dır'], '−3 ile çarpma sıralamayı tersine çevirir; en küçük değer −2, g\'de en büyük değer 6 olur.'),
  ('f\'nin sıfırları −4, 0 ve 6\'dır. g(x) = f(2x) fonksiyonunun sıfırları hangileridir?', '−2, 0 ve 3', ['−8, 0 ve 12', '−4, 0 ve 6', '−2, 2 ve 3'], 'f(2x) = 0 için 2x, f\'nin sıfırlarından biri olmalıdır; x = −2, 0, 3 bulunur.'),
  ('f\'nin görüntü kümesi [−1, 4] ise y = |f(x)| fonksiyonunun görüntü kümesi hangisidir?', '[0, 4]', ['[1, 4]', '[−1, 4]', '[0, 5]'], '−1 ile 0 arasındaki değerler pozitife döner (0 ile 1 arası); 0 ile 4 arası değişmez. Sonuç [0, 4]\'tür.'),
  ('y = a·2ˣ (a > 0) grafiğinde a değeri büyüdükçe hangi özellik değişir?', 'Grafiğin y eksenini kestiği nokta yükselir', ['Grafiğin yatay asimptotu da a ile birlikte yukarı kayar', 'Grafik azalan hâle gelir', 'Grafik x eksenini kesmeye başlar'], 'x = 0\'da y = a\'dır; a büyüdükçe kesişim yükselir. Asimptot y = 0 olarak kalır ve fonksiyon artan olmaya devam eder.'),
  ('y = 3ˣ ile y = 3^(−x) grafiklerinin kesiştiği nokta hangisidir?', '(0, 1)', ['(1, 3)', '(0, 3)', '(1, 1/3)'], '3ˣ = 3^(−x) ise x = −x, yani x = 0\'dır; burada y = 1 olur.'),
  ('y = (1/2)ˣ fonksiyonu için x = −3 noktasındaki değer kaçtır?', '8', ['−8', '1/8', '−1/8'], '(1/2)^(−3) = 2³ = 8\'dir; azalan üstel fonksiyon solda büyük değerler alır.'),
  ('Üssünde mutlak değer bulunan 2^|x| kuralının eğrisi için doğru betimleme hangisidir?', 'y eksenine göre simetriktir ve en küçük değeri 1\'dir', ['Orijine göre simetriktir', 'Her yerde artandır ve x eksenine soldan yaklaşır', 'En büyük değeri 1\'dir'], '2^|−x| = 2^|x| olduğundan çifttir. |x| ≥ 0 olduğundan 2^|x| ≥ 1\'dir; eşitlik x = 0\'dadır.'),
  ('y = ln x ile y = log x (on tabanlı) grafikleri x > 1 bölgesinde nasıl konumlanır?', 'ln x eğrisi log x eğrisinin üstündedir', ['log x eğrisi ln x eğrisinin her zaman üstünde kalır', 'İki eğri çakışıktır', 'İki eğri x = 2\'de kesişir'], 'x > 1 için ln x = log x · ln 10 ≈ 2,3·log x olduğundan ln x daha büyüktür. İkisi yalnız x = 1\'de kesişir.'),
  ('y = log₂(x²) ile y = 2·log₂x fonksiyonları neden aynı değildir?', 'İlki x < 0 için de tanımlı, ikincisi değildir', ['İkisi her x için farklı değer verir', 'İlki yalnız x > 1 için tanımlıdır', 'İkincisi negatif değer alamaz'], 'log₂(x²) her x ≠ 0 için tanımlıdır; 2·log₂x yalnız x > 0 için. Pozitif x\'lerde değerleri aynıdır, tanım kümeleri farklıdır.'),
  ('y = log₃(x − 2) grafiği (11, k) noktasından geçiyorsa k kaçtır?', '2', ['3', '9', '1'], 'log₃(11 − 2) = log₃9 = 2\'dir.'),
  ('Önüne eksi işareti konan −log₂x eğrisi, log₂x eğrisinden hangi işlemle elde edilir?', 'x eksenine göre yansıtılarak', ['y eksenine göre yansıtılarak', 'y = x doğrusuna göre yansıtılarak', '2 birim aşağı ötelenerek'], 'Fonksiyonun önündeki eksi işareti x eksenine göre yansımadır; sonuç aynı zamanda log₀,₅x grafiğidir.'),
  ('y = log₂x fonksiyonunun görüntü kümesi neden bütün gerçek sayılardır?', 'Her gerçek y için 2^y pozitif bir girdi verir', ['Tanım kümesi bütün gerçek sayılar olduğu için', 'Fonksiyon y eksenine göre simetrik olduğu için', 'Fonksiyon her yerde negatif olduğu için'], 'log₂x = y eşitliği x = 2^y ile çözülür; her y için 2^y > 0 olduğundan uygun bir x vardır.'),
  ('Bir makine benzetmesinde fonksiyon için hangisi doğrudur?', 'Aynı girdi her seferinde aynı çıktıyı verir', ['Aynı girdi farklı zamanlarda farklı çıktı verebilir', 'Her çıktı tek bir girdiden gelmelidir', 'Girdi ile çıktı her zaman eşittir'], 'Fonksiyonda girdi çıktıyı tek biçimde belirler. Farklı girdilerin aynı çıktıyı vermesi ise serbesttir.'),
  ('y = log₂x ve y = 3 − x grafikleri kaç noktada kesişir?', '1', ['0', '2', '3'], 'log₂x artan, 3 − x azalandır; en çok bir kez kesişirler. x = 2\'de log₂2 = 1 ve 3 − 2 = 1 olduğundan kesişim (2, 1)\'dir.'),
  ('f artan, g azalan fonksiyonlar ise f∘g bileşkesi için hangisi kesindir?', 'Azalandır', ['Artandır', 'Sabittir', 'Artan da azalan da olabilir'], 'x büyüyünce g(x) küçülür; f artan olduğundan f(g(x)) de küçülür. Bileşke azalandır.'),
  ('f ve g ikisi de azalan fonksiyonlarsa f∘g bileşkesi nasıldır?', 'Artandır', ['Azalandır', 'Sabittir', 'Tek fonksiyondur'], 'x artınca g(x) azalır; azalan f, daha küçük girdiye daha büyük çıktı verir. İki azalma birleşince artış oluşur.'),
  ('f(x) = 2 − x ve g(x) = x³ ise (f∘g)(x) fonksiyonu gerçek sayılarda nasıl davranır?', 'Azalandır', ['Artandır', 'Önce artar sonra azalır', 'Sabittir'], '(f∘g)(x) = 2 − x³\'tür; x³ artan olduğundan 2 − x³ azalandır.'),
  ('(−∞, 0] aralığında tanımlı f(x) = x² fonksiyonunun tersi hangisidir?', '−√x', ['√x', '√(−x)', 'x²'], 'Bu aralıkta f birebirdir ve çıktıları [0, ∞)\'dadır. y = x² ve x ≤ 0 ise x = −√y olur.'),
  ('y = √(2x − 6) fonksiyonunun grafiği hangi noktadan başlar?', '(3, 0)', ['(6, 0)', '(0, 3)', '(−3, 0)'], 'Kök içi 2x − 6 = 0 için x = 3\'tür; burada y = 0 olur.'),
  ('y = ⌊x⌋ ile y = x grafiklerinin ortak noktaları hangileridir?', 'Apsisi tam sayı olan bütün (n, n) noktaları', ['Yalnız orijin', 'Hiç ortak nokta yoktur', 'Apsisi pozitif olan ve y = x doğrusu üzerindeki bütün noktalar'], '⌊x⌋ = x eşitliği yalnız x tam sayı iken sağlanır; bu noktalar y = x doğrusunun tam sayı koordinatlı noktalarıdır.'),
  ('x − ⌊x⌋ fonksiyonunun grafiği hangi biçimdedir?', 'Eğimi 1 olan, her tam sayıda 0\'a düşen testere dişi', ['Her tam sayıda bir birim yukarı sıçrayan yatay basamaklar', 'Orijinden geçen tek bir doğru', 'V biçimli bir grafik'], 'Her [n, n + 1) aralığında değer 0\'dan başlayıp 1\'e yaklaşarak doğrusal artar, sonraki tam sayıda 0\'a düşer.'),
  ('C(t) = 10t/(t² + 1) derişim modelinde t çok büyüdükçe derişim nasıl davranır?', 'Sıfıra yaklaşır', ['10\'a yaklaşır', 'Sınırsız artar', '1\'e yaklaşır'], 'Paydanın derecesi paydan büyük olduğundan oran sıfıra yaklaşır; ilaç zamanla vücuttan atılır.'),
  ('P(d) = 60d/(d + 4) öğrenme modelinde günlük üretim hangi değeri hiçbir zaman aşamaz?', '60', ['40', '4', '15'], '60d/(d + 4) < 60\'tır çünkü pay paydanın 60 katından küçüktür; d büyüdükçe değer 60\'a yaklaşır.'),
  ('f(x) = x³ − 4x fonksiyonunun grafiği x eksenini kaç noktada keser?', '3', ['2', '1', '4'], 'x(x² − 4) = 0 ise x = 0, 2, −2\'dir; üç kesişim vardır.'),
  ('y = 1/x² fonksiyonunun grafiği yatay doğru testine göre nasıl sınıflandırılır?', 'Testi geçemez; y = 1 doğrusu grafiği iki noktada keser', ['Testi geçer; fonksiyon birebirdir', 'Testi geçer; çünkü fonksiyon x = 0\'da tanımsız olduğundan iki kola ayrılır', 'Testi geçemez; çünkü fonksiyon değildir'], '1/x² = 1 eşitliği x = 1 ve x = −1 için sağlanır; birebir değildir.'),
  ('Gerçek sayılarda tanımlı f(x) = x³ + 2 fonksiyonu için hangisi doğrudur?', 'Tek değildir ama grafiği (0, 2) noktasına göre simetriktir', ['Tek fonksiyondur', 'Çift fonksiyondur', 'Grafiği y eksenine göre simetriktir'], 'f(0) = 2 ≠ 0 olduğundan tek değildir. x³ grafiğinin 2 birim yukarı ötelemesi olduğundan simetri merkezi (0, 2)\'dir.'),
  ('Küp alma fonksiyonunun −1 ile 1 arasındaki ortalama değişim hızı kaçtır?', '1', ['0', '2', '3'], '[1 − (−1)]/[1 − (−1)] = 2/2 = 1\'dir.'),
  ('Bir aralıkta ortalama değişim hızı negatif olan bir fonksiyon için hangisi kesindir?', 'Aralığın sonundaki değer başındakinden küçüktür', ['Fonksiyon aralığın her yerinde, her noktada azalan olmak zorundadır', 'Fonksiyonun bütün değerleri negatiftir', 'Fonksiyon aralıkta sabittir'], 'Ortalama değişim hızı yalnız uç değerlerin farkına bakar; aradaki davranış hakkında kesin bilgi vermez.'),
  ('Bir dikdörtgenin alanı hem kısa kenarına hem uzun kenarına bağlıysa bu durum nasıl ifade edilir?', 'Alan iki değişkenli bir fonksiyondur', ['Alan bir fonksiyon olamaz, çünkü iki ayrı girdiye bağlıdır', 'Alan yalnız kısa kenarın fonksiyonudur', 'Alan sabit bir fonksiyondur'], 'A(a, b) = a·b biçiminde iki girdisi olan bir fonksiyondur; her (a, b) ikilisine tek bir alan karşılık gelir.'),
];
